 function guideFeature0(document, window, fetch, ResizeObserver, setTimeout, clearTimeout, setInterval, clearInterval, requestAnimationFrame, cancelAnimationFrame, navigator) {

    (function(){
      var modal = document.getElementById('imageModal');
      var modalImg = document.getElementById('imageModalImg');
      var modalCaption = document.getElementById('imageModalCaption');
      var modalClose = document.getElementById('imageModalClose');
      var zoomables = document.querySelectorAll('.zoomable');
      var lastFocused = null;

      function openModal(src, alt, title){
        if (!src) return;
        lastFocused = document.activeElement;
        modalImg.src = src;
        modalImg.alt = alt || title || '확대 이미지';
        modalCaption.textContent = title || alt || '';
        modal.classList.add('is-open');
        modal.setAttribute('aria-hidden', 'false');
        document.body.classList.add('modal-open');
        modalClose.focus();
      }

      function closeModal(){
        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
        modalImg.src = '';
        modalImg.alt = '';
        modalCaption.textContent = '';
        document.body.classList.remove('modal-open');
        if (lastFocused) lastFocused.focus();
      }

      zoomables.forEach(function(img){
        img.addEventListener('click', function(){
          openModal(
            img.getAttribute('data-zoom-src') || img.getAttribute('src'),
            img.getAttribute('alt'),
            img.getAttribute('data-zoom-title')
          );
        });

        img.addEventListener('keydown', function(e){
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            openModal(
              img.getAttribute('data-zoom-src') || img.getAttribute('src'),
              img.getAttribute('alt'),
              img.getAttribute('data-zoom-title')
            );
          }
        });

        img.setAttribute('tabindex', '0');
        img.setAttribute('role', 'button');
        img.setAttribute('aria-label', (img.getAttribute('data-zoom-title') || img.getAttribute('alt') || '이미지') + ' 확대 보기');
      });

      modalClose.addEventListener('click', closeModal);

      modal.addEventListener('click', function(e){
        if (e.target === modal) closeModal();
      });

      document.addEventListener('keydown', function(e){
        if (e.key === 'Escape' && modal.classList.contains('is-open')) {
          closeModal();
        }
      });
    })();
  
}

