function guideFeature4(document, window, fetch, ResizeObserver, setTimeout, clearTimeout, setInterval, clearInterval, requestAnimationFrame, cancelAnimationFrame, navigator) {

    (function(){
      var mqMobile = window.matchMedia('(max-width: 900px)');

      function setupMobilePreview(){
        var shell = document.getElementById('mobile-preview-shell');
        var stage = document.getElementById('mobile-preview-stage');
        var sourceTable = document.getElementById('prep-guide-table');
        if(!shell || !stage || !sourceTable) return;

        if(window.innerWidth > 768){
          stage.innerHTML = '';
          shell.style.height = '';
          return;
        }

        stage.innerHTML = '';
        var clone = sourceTable.cloneNode(true);
        clone.removeAttribute('id');
        clone.setAttribute('aria-hidden', 'true');
        stage.appendChild(clone);

        var baseWidth = clone.offsetWidth || 980;
        var shellWidth = shell.clientWidth || (window.innerWidth - 28);
        var scale = Math.min(shellWidth / baseWidth, 1);
        if(scale < 0.28) scale = 0.28;

        stage.style.transform = 'scale(' + scale + ')';
        stage.style.width = baseWidth + 'px';
        shell.style.height = Math.ceil(clone.offsetHeight * scale) + 'px';
      }

      function openTableModal(){
        var modal = document.getElementById('table-modal');
        var content = document.getElementById('table-modal-content');
        var sourceTable = document.getElementById('prep-guide-table');
        if(!modal || !content || !sourceTable) return;

        content.innerHTML = '';
        var clone = sourceTable.cloneNode(true);
        clone.removeAttribute('id');
        clone.setAttribute('aria-hidden', 'true');
        content.appendChild(clone);

        modal.classList.add('is-open');
        modal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }

      function closeTableModal(){
        var modal = document.getElementById('table-modal');
        var content = document.getElementById('table-modal-content');
        if(!modal || !content) return;

        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
        content.innerHTML = '';
        document.body.style.overflow = '';
      }

      function bindModalEvents(){
        var openBtn = document.getElementById('mobile-preview-open');
        var closeBtn = document.getElementById('table-modal-close');
        var modal = document.getElementById('table-modal');

        if(openBtn){
          openBtn.addEventListener('click', function(){
            if(window.innerWidth <= 768){
              openTableModal();
            }
          });
        }

        if(closeBtn){
          closeBtn.addEventListener('click', closeTableModal);
        }

        if(modal){
          modal.addEventListener('click', function(e){
            if(e.target === modal){
              closeTableModal();
            }
          });
        }

        document.addEventListener('keydown', function(e){
          if(e.key === 'Escape'){
            closeTableModal();
          }
        });
      }

      function initStickyObservers(){

        if(mqMobile && mqMobile.addEventListener){
          mqMobile.addEventListener('change', function(){
            setupMobilePreview();
            closeTableModal();
          });
        }else if(mqMobile && mqMobile.addListener){
          mqMobile.addListener(function(){
            setupMobilePreview();
            closeTableModal();
          });
        }

        if(window.ResizeObserver){
          var ro = new ResizeObserver(function(){
            setupMobilePreview();
          });
          var shell = document.getElementById('mobile-preview-shell');
          if(shell) ro.observe(shell);
        }

        window.addEventListener('load', function(){
          setupMobilePreview();
        });
        window.addEventListener('resize', function(){
          setupMobilePreview();
        });
      }

      initStickyObservers();
      setupMobilePreview();
      bindModalEvents();
    })();
  
}

