      function statAtSegments(H,L){
        let s=H.base;
        for(const item of H.seg){
          const f=item[0], t=item[1], d=item[2];
          if(L<f) break;
          const u=Math.min(L,t);
          s += (u-f+1)*d;
          if(L<=t) break;
        }
        return s;
      }

      function deltaAt(H,L){
        for(const item of H.seg){
          if(L>=item[0] && L<=item[1]) return item[2];
        }
        return null;
      }

      function anchorLevel(name, level, target){
        const H=SEG[name];
        if(!H) return;
        let i=-1;
        for(let idx=0; idx<H.seg.length; idx++){
          const f=H.seg[idx][0], t=H.seg[idx][1];
          if(level>=f && level<=t){ i=idx; break; }
        }
        if(i>=0){
          const seg=H.seg[i];
          const f=seg[0], t=seg[1], d=seg[2];
          if(!(f===level && t===level)){
            const left=(level-1>=f)?[f,level-1,d]:null;
            const right=(level<=t)?[level,t,d]:null;
            const repl=[];
            if(left) repl.push(left);
            if(right) repl.push(right);
            H.seg.splice(i,1);
            for(let r=repl.length-1;r>=0;r--) H.seg.splice(i,0,repl[r]);
          }
        }
        const need=+(target - statAtSegments(H,level-1)).toFixed(4);
        let j=-1;
        for(let idx=0; idx<H.seg.length; idx++){
          if(H.seg[idx][0]===level && H.seg[idx][1]===level){ j=idx; break; }
        }
        const fixed=[level,level,need];
        if(j>=0) H.seg[j]=fixed; else H.seg.push(fixed);
      }

      function fillLastCycleFromGen2(name){
        const H=SEG[name];
        const G2=SEG.Hilde;
        if(!H || !G2) return;
        const d2526 = deltaAt(H,25);
        const g22526 = deltaAt(G2,25);
        if(d2526==null || g22526==null) return;
        const patt = [deltaAt(G2,27), deltaAt(G2,28), deltaAt(G2,29)];
        const k = d2526 / g22526;
        [27,28,29].forEach(function(L, idx){
          if(deltaAt(H,L)!=null) return;
          const d = +((patt[idx]||0) * k).toFixed(4);
          H.seg.push([L,L,d]);
        });
        H.seg.sort(function(a,b){ return a[0]-b[0]; });
      }

      ['Eric','Petra','Jaeger'].forEach(fillLastCycleFromGen2);
