    function calcTotalsPerTG(){
      const out = Array.from({length: TG_MAX}, () => ({ truegold:0, tempered:0, hasTruegold:false, hasTempered:false }));

      for (let i = 0; i < TG_MAX; i++){
        let tgSum = 0;
        let tpSum = 0;
        let hasTg = false;
        let hasTp = false;

        for (const b of BUILDINGS){
          const r = DATA[b.key];
          const tv = r.truegold[i];
          const pv = r.tempered[i];

          if (isNum(tv)){
            tgSum += Number(tv);
            hasTg = true;
          }
          if (isNum(pv)){
            tpSum += Number(pv);
            hasTp = true;
          }
        }

        out[i].truegold = tgSum;
        out[i].tempered = tpSum;
        out[i].hasTruegold = hasTg;
        out[i].hasTempered = hasTp;
      }

      return out;
    }

